import numpy as np
import os, sys
try:
    from scipy.optimize import linprog
except Exception:
    linprog = None

# Import core utilities for exact radii LP and finalize
sys.path.append('storage/verity')
try:
    import scp_lp_core as core
except Exception:
    core = None

N = 32
R_MIN = 1e-8

# ---------------- Utilities ----------------
def _pair_indices(n=N):
    return [(i, j) for i in range(n) for j in range(i + 1, n)]

PAIRS = _pair_indices(N)

def _seed_storage_best():
    try:
        C = np.load("storage/verity/best_centers.npy")
        if isinstance(C, np.ndarray) and C.shape == (N, 2):
            return np.clip(C.astype(float), 0.0, 1.0)
    except Exception:
        pass
    return None

def _seed_storage_best_jitter(amp=0.002, seed=7001):
    C = _seed_storage_best()
    if C is None:
        return None
    rng = np.random.default_rng(seed)
    jitter = rng.uniform(-amp, amp, size=C.shape)
    return np.clip(C + jitter, 0.0, 1.0)

def _fallback_grid():
    xs = np.linspace(0.1, 0.9, 6)
    ys = np.linspace(0.1, 0.9, 6)
    centers = []
    for ix, x in enumerate(xs):
        for iy, y in enumerate(ys):
            if (ix in (0, 5)) and (iy in (0, 5)):
                continue  # 36 - 4 = 32
            centers.append([x, y])
    return np.array(centers, dtype=float)

# ---------------- Exact radii LP (zero slack) fallback if core unavailable ----------------
def _solve_radii_lp_zero_slack(C):
    if core is not None:
        return core.solve_radii_lp_zero_slack(C)
    # Minimal inline fallback
    if linprog is None:
        x, y = C[:, 0], C[:, 1]
        r = np.maximum(R_MIN, np.minimum.reduce([x, 1.0 - x, y, 1.0 - y]))
        return r, False
    n = C.shape[0]
    rows, rhs = [], []
    x, y = C[:, 0], C[:, 1]
    for i in range(n):
        a = np.zeros(n); a[i] = 1.0; rows.append(a); rhs.append(max(0.0, float(x[i])))
    for i in range(n):
        a = np.zeros(n); a[i] = 1.0; rows.append(a); rhs.append(max(0.0, float(1.0 - x[i])))
    for i in range(n):
        a = np.zeros(n); a[i] = 1.0; rows.append(a); rhs.append(max(0.0, float(y[i])))
    for i in range(n):
        a = np.zeros(n); a[i] = 1.0; rows.append(a); rhs.append(max(0.0, float(1.0 - y[i])))
    for (i, j) in PAIRS:
        a = np.zeros(n); a[i] = 1.0; a[j] = 1.0
        dij = float(np.linalg.norm(C[i] - C[j]))
        rows.append(a); rhs.append(max(0.0, dij))
    A_ub = np.vstack(rows) if rows else None
    b_ub = np.array(rhs) if rows else None
    c = -np.ones(n)
    bounds = [(R_MIN, None) for _ in range(n)]
    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method="highs")
    if not res.success:
        r = np.maximum(R_MIN, 0.99 * np.minimum.reduce([x, 1.0 - x, y, 1.0 - y]))
        return r, False
    return np.maximum(R_MIN, np.array(res.x, dtype=float)), True

def _finalize_minimal(C, r, neg_tol=0.0):
    if core is not None:
        return core.finalize_minimal(C, r, neg_tol=neg_tol)
    # Inline minimal finalize: fix only true violations; equality allowed
    r = r.copy()
    x, y = C[:, 0], C[:, 1]
    for i in range(N):
        if x[i] - r[i] < -neg_tol:
            r[i] = max(R_MIN, min(r[i], x[i]))
        if 1.0 - x[i] - r[i] < -neg_tol:
            r[i] = max(R_MIN, min(r[i], 1.0 - x[i]))
        if y[i] - r[i] < -neg_tol:
            r[i] = max(R_MIN, min(r[i], y[i]))
        if 1.0 - y[i] - r[i] < -neg_tol:
            r[i] = max(R_MIN, min(r[i], 1.0 - y[i]))
    for (i, j) in PAIRS:
        dij = float(np.linalg.norm(C[i] - C[j]))
        s = r[i] + r[j]
        if s - dij > neg_tol:
            need = (s - dij)
            take_i = min(0.5 * need, max(0.0, r[i] - R_MIN))
            take_j = min(0.5 * need, max(0.0, r[j] - R_MIN))
            rem = need - (take_i + take_j)
            if rem > 0:
                extra_i = min(rem, max(0.0, r[i] - R_MIN - take_i)); take_i += extra_i; rem -= extra_i
            if rem > 0:
                extra_j = min(rem, max(0.0, r[j] - R_MIN - take_j)); take_j += extra_j; rem -= extra_j
            r[i] = max(R_MIN, r[i] - take_i)
            r[j] = max(R_MIN, r[j] - take_j)
    return r

# ---------------- Active-constraint SCP-LP ----------------
def _select_active_pairs(C, r, K):
    # Compute slacks and pick K smallest pair slacks
    items = []
    for (i, j) in PAIRS:
        dvec = C[i] - C[j]
        dij = float(np.linalg.norm(dvec))
        s = dij - (r[i] + r[j])
        items.append((s, i, j, dvec, dij))
    items.sort(key=lambda t: t[0])
    sel = items[:K]
    # Build unit vectors
    act = []
    for (s, i, j, dvec, dij) in sel:
        if dij < 1e-12:
            u = np.array([1.0, 0.0])
        else:
            u = dvec / dij
        act.append((i, j, u))
    return act

def _build_linearized_mats_active(C0, tau, active_pairs):
    if linprog is None:
        return None
    n = C0.shape[0]; m = 3 * n
    rows, rhs = [], []

    # Pairwise constraints for active subset:
    # r_i + r_j - u_x (x_i - x_j) - u_y (y_i - y_j) <= 0
    for (i, j, u) in active_pairs:
        row = np.zeros(m)
        row[2*n + i] = 1.0; row[2*n + j] = 1.0
        row[i] -= u[0]; row[j] += u[0]
        row[n + i] -= u[1]; row[n + j] += u[1]
        rows.append(row); rhs.append(0.0)

    # Boundary ties (zero slack)
    for i in range(n):
        row = np.zeros(m); row[2*n + i] = 1.0; row[i] -= 1.0
        rows.append(row); rhs.append(0.0)
        row = np.zeros(m); row[2*n + i] = 1.0; row[i] += 1.0
        rows.append(row); rhs.append(1.0)
        row = np.zeros(m); row[2*n + i] = 1.0; row[n + i] -= 1.0
        rows.append(row); rhs.append(0.0)
        row = np.zeros(m); row[2*n + i] = 1.0; row[n + i] += 1.0
        rows.append(row); rhs.append(1.0)

    A_ub = np.vstack(rows) if rows else None
    b_ub = np.array(rhs) if rows else None

    x0 = C0[:, 0]; y0 = C0[:, 1]
    x_lb = np.maximum(0.0, x0 - tau); x_ub = np.minimum(1.0, x0 + tau)
    y_lb = np.maximum(0.0, y0 - tau); y_ub = np.minimum(1.0, y0 + tau)

    bounds = []
    for i in range(n): bounds.append((float(x_lb[i]), float(x_ub[i])))
    for i in range(n): bounds.append((float(y_lb[i]), float(y_ub[i])))
    for i in range(n): bounds.append((R_MIN, None))

    c = np.zeros(m); c[2*n:] = -1.0
    return A_ub, b_ub, bounds, c

def _lp_step_active(C0, tau, active_pairs):
    mats = _build_linearized_mats_active(C0, tau, active_pairs)
    if mats is None:
        return None, None
    A_ub, b_ub, bounds, c = mats
    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method="highs")
    if not res.success:
        return None, None
    n = C0.shape[0]
    x = res.x
    X = x[:n]; Y = x[n:2*n]; R = x[2*n:]
    C_new = np.stack([X, Y], axis=1)
    return C_new, R

def _candidate_optimize_active(Cinit, K_pairs=5*N, max_outer=80, verbose=False):
    # Use zero-slack radii on full constraints; active subset only for center step
    C = Cinit.copy()
    r0, _ = _solve_radii_lp_zero_slack(C)
    best_C = C.copy(); best_r = r0.copy(); best_s = float(np.sum(best_r))
    if verbose: print(f"[start] {best_s:.9f}")
    tau = 0.06; min_tau = 5e-4; no_improve = 0; patience = 16
    alphas = [1.0, 0.9, 0.75, 0.6, 0.5, 0.4, 0.3, 0.2, 0.12, 0.08, 0.05]

    for it in range(max_outer):
        # Select active subset based on current (C, best_r)
        active = _select_active_pairs(C, best_r, int(K_pairs))
        step = _lp_step_active(C, tau, active)
        if step[0] is None:
            tau *= 0.6
            if tau < min_tau: break
            continue
        C_lin, _ = step
        # Backtracking along linearized direction with full radii LP re-solve
        d = C_lin - C
        accepted = False
        best_local_C = None; best_local_r = None; best_local_s = -1.0
        for a in alphas:
            C_try = np.clip(C + a * d, 0.0, 1.0)
            r_try, ok = _solve_radii_lp_zero_slack(C_try)
            if not ok:
                continue
            s_try = float(np.sum(r_try))
            if s_try > best_local_s:
                best_local_s = s_try; best_local_C = C_try; best_local_r = r_try
            if s_try > best_s + 1e-6:
                # Accept first improving alpha (greedy)
                C = C_try; best_C = C_try; best_r = r_try; best_s = s_try
                tau = min(0.12, tau * 1.05)
                no_improve = 0
                accepted = True
                if verbose: print(f"[it {it:02d}] accept a={a:.2f} score={best_s:.9f} K={K_pairs}")
                break
        if not accepted:
            # No alpha improved; tighten tau and continue
            tau *= 0.6; no_improve += 1
            if verbose: print(f"[it {it:02d}] reject score={best_s:.9f} tau={tau:.4f}")
            if tau < min_tau or no_improve >= patience:
                break

    # Finalize (idempotent if exact)
    best_r = _finalize_minimal(best_C, best_r, neg_tol=0.0)
    return best_C, best_r, best_s

# ---------------- Main ----------------
def construct_packing() -> tuple:
    seeds = []
    C0 = _seed_storage_best()
    if C0 is not None:
        seeds.append(("storage-best", C0))
        Cj = _seed_storage_best_jitter(amp=0.001, seed=7307)
        if Cj is not None:
            seeds.append(("storage-best-jitter-0.001", Cj))
    else:
        seeds.append(("grid-36minus4", _fallback_grid()))

    best_sum = -1.0; best_C = None; best_r = None
    for name, C in seeds:
        print(f"[seed] {name}")
        C = np.clip(C, 0.0, 1.0)
        C_opt, r_opt, s = _candidate_optimize_active(C, K_pairs=5*N, max_outer=80, verbose=False)
        print(f"[seed] {name} -> score {s:.9f}")
        if s > best_sum:
            best_sum, best_C, best_r = s, C_opt, r_opt

    try:
        os.makedirs("storage/verity", exist_ok=True)
        np.save("storage/verity/best_centers.npy", best_C)
        np.save("storage/verity/best_radii.npy", best_r)
    except Exception:
        pass

    return np.array(best_C, dtype=float), np.array(best_r, dtype=float)
